    for (var i = 0; i < tables.length; i++) {
        var table = tables[i];

        // Deselected rows
        table.querySelectorAll("tr").forEach(function (row) {
            row.classList.remove("selected-row");
        });

        // Sort columns by default
        for (var colIndex = 0; colIndex < keys.length; colIndex++) {
            if (!table.querySelector('th[aria-controls="' + keys[colIndex] + '"]')) continue;

            if (colIndex !== keys[colIndex]) {
                // Rearrange columns that aren't sorted by their key
                var cols = table.querySelectorAll("td[aria-controls='" + keys[colIndex] + "']") || [table.children[0]];
                cols.forEach(function (c) { c.remove(); });

                var newColumns = [];
                for (var idx = 0; idx < keys.length; idx++) {
                    var thElement = table.querySelector('th[aria-controls="' + keys[idx] + '"]');
                    if (thElement)
                        newColumns.push(thElement);
                    else
                        break;
                }
                console.log(newColumns);

                // Place the remaining columns at the top of the table
                if (newColumns.length > 0) {
                    table.insertAdjacentHTML("afterbegin", "<tr>" + newColumns.map(function (el) { return el.outerHTML }).join("") + "</tr>");
                }

                // Manually sort cells based on column index using the header's value
                var sortedItems = Array.from(table.rows).sort((a, b) => {
                    let valA = parseInt(a.cells[colIndex].textContent.replace(/[^0-9]/g, ""));
                    let valB = parseInt(b.cells[colIndex].textContent.replace(/[^0-9]/g, "")); // Children can be NaN

                    if (valA === valB) return 0;
                    if (valA < valB) return -1;
                    if (valA > valB) return 1;

                    return 0;
                });

                // Rebuild the table with sorted columns
                const tbody = table.getElementsByTagName("tbody")[0];
                tbody.innerHTML = "";
                sortedItems.forEach(row => tbody.appendChild(row));
            }
        }
    }
});
</script>

