struct Evaluation {
    pub company_names: String,
    pub url: String,
    pub summary: String,
}

impl Evaluation {
    fn new(company_names: &str, url: &str, summary: &str) -> Self {
        let evaluated = match company_names.split_once(",").map_or("", |_| "s")
            .trim();
        let interpolated = format!("{}{}", evaluated.trim_matches(' '), summary);

        Evaluation {
            company_names: company_names.to_string(),
            url: url.to_string(),
            summary: interpolated.trim_end().to_string(),
        }
    }

    #[inline]
    fn clean_company_name(companies: &[String]) -> Option<String> {
        if companies.len() == 0 {
            return None;
        }
        if companies.iter()
            .all(|company| company.starts_with(" "))
            && companies.first()
                .unwrap()
                .starts_with(" ")
        {
            return Some(String::from(""));
        }
        None
    }

    fn slice_sasimo(s: &str) -> Option<&str> {
        if s.is_empty() || !s.contains(',') {
            return None;
        }
        let parts: Vec<&str> = s.split(',').collect();
        if parts.len() > 2 {
            return Some(parts[0]);
        }
        if parts.len() == 1 {
            return Some(parts[0]);
        }
        if parts.len() == 2 {
            return Some(parts[1]);
        }
        None
    }

    fn build_viz_48(bg_color: Color, bar_graph_name: &str, h_rem: usize) -> String {
        // Create a canvas size that's 48x24 units filled with the background color
        let width = 48 + h_rem * 3;
        let height = 24 + h_rem;

        // Draw bar chart using buffer allocation
        let mut data: Vec<f64> = vec![0.0_f64; width];
        let mut current = 0_f64;
        let mut product = 0.0;

        for x in 0..width {
            if x % 10 == 1 {
                current += 1.0;
                product = 0.0;
                continue;
            }
            if x % 10 == 5 {
                product *= ((x as f64) / 10.0) * 0.30f64;
            }
            data[x] = product;
        }

        let baseline = 10.0_f64;
        let baseline_split = 5.0_f64;

        let mut result = String::with_capacity(width * 2);
        for row in 0..height {
            for col in 0..width {
                let cell_height = (data[col] / 10.0_f64) * baseline;
                let delta_y = (cell_height + baseline_split) * 2.0_f64;
                let bottom_line = (row + 1) * delta_y;

                result.push_str(format!("{:.0} ", (col + 1) * 1.0_f64));
                result.push_str(format!("{}{:.2}", ("#" as char), (delta_y + baseline_split)));
                result.push('\n');
            }
        }
        result
    }

