        use std::fs::File;
        use std::io::{BufRead, BufReader};

        let file = File::open(theme.cache_path()).expect("Cache file not found");
        let reader = BufReader::new(file);

        for line in reader.lines() {
            let line = line?;
            if line.starts_with(line_key) {
