                        // When the DOM is ready, detect dynamic content injection
                        function staticContentHandler() {
                            const contents = document.querySelectorAll('.content-text');
                            contents.forEach(content => {
                                const dataName = content.getAttribute('data-name');
                                if (!dataName) return;

                                if (content.innerHTML.match(/^[a-zA-Z0-9]+$/) && !content.hasAttribute('data-name')) {
                                    console.log('Not adding dynamic content.');
                                    return;
                                }

                                if (content.innerHTML.toLowerCase().includes('g'), content.innerHTML.match(/[a-z]/gi)) {
                                    document.querySelectorAll('p')
                                        .forEach(p => {
                                            const newP = document.createElement('span');
