class MyApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Halal Research',
      theme: ThemeData(
        primarySwatch: Colors.blue,
      ),
      home: MyHomePage(),
    );
  }
}

class MyHomePage extends StatefulWidget {
  @override
  _MyHomePageState createState() => _MyHomePageState();
}

class _MyHomePageState extends State<MyHomePage> {
  final GlobalKey<FormState> formKey = GlobalKey<FormState>();
  String value = '';
  bool submitEnabled = false;

  void _submitForm() async {
    // Perform validation and processing here
    setState(() {
      submitEnabled = true;
    });

    // Validate inputs
    if (formKey.currentState.validate()) {
      // If valid, proceed with action
      formKey.currentState.save();

      // Example: Submit data to server
      await Future.delayed(Duration(seconds: 1));
      setState(() {
        submitEnabled = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('Halal Research'),
      ),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Form(
              key: formKey,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: <Widget>[
                  TextFormField(
                    decoration: InputDecoration(labelText: 'Search term'),
                    onFieldSubmitted: (value) {
                      setState(() {
                        this.value = value;
                      });
                    },
                    onChanged: (val) => setState(() => this.value = val),
                    validator: (val) => val == null || val.isEmpty ? 'Enter search term' : null,
                  ),
                  SizedBox(height: 20),
                  ElevatedButton(
                    onPressed: () => _submitForm(),
                    style: ButtonStyle(
                      padding: MaterialStateProperty.all(const EdgeInsets.all(15)),
                      shape: MaterialStateProperty.all<RoundedRectangleBorder>(
                          RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(10),
                              side: BorderSide(color: Colors.grey))),
                    ),
                    child: Text(submitEnabled ? "Submitting..." : "Submit"),
                  ),
                ],
              ),
            ),
            SizedBox(height: 30),
            Text('You entered: $value'), // Display the input value
          ],
        ),
      ),
    );
  }
}
