const writeStreamFromSettings = async function (inputData, userPreferences, taskLevel) {  
  return new Promise((resolve, reject) => {
    const fontFamily = userPreferences.fontFamily || 'Arial';
    const fontSize = userPreferences.fontSize || 14;
    const fontWeight = userPreferences.fontWeight || 'normal';
    const color = userPreferences.color || '#333333';
    const theme = userPreferences.theme || 'light';

    if (!fontFamily || !fontSize || !fontWeight || !color) {
      console.error('Invalid preferences');
      resolve(null);
      return;
    }

    try {
      const stream = fs.createWriteStream('output.txt', { encoding: 'utf-8' });
      const writer = stream.getWriter();
      const stringToWrite = inputData ? inputData : 'No input provided.';
      writer.write(stringToWrite);
      await writer.close();
      resolve({ success: true, message: 'File written successfully.' });
    } catch (error) {
      console.error('Error writing file:', error.message);
      resolve({ success: false, message: 'Error occurred while writing the file.' });
    }
  });
};

