import 'package:flutter/material.dart';

class GuestDate extends StatefulWidget {
  const GuestDate({Key? key}) : super(key: key);

  @override
  _GuestDateState createState() => _GuestDateState();
}

class _GuestDateState extends State<GuestDate> {
  final List<String> suggestions = [
    "Saturday",
    "Monday",
    "Friday",
    "Wednesday",
    "Thursday"
  ];

  void selectDay(String day) {
    setState(() {
      selectedDay = day;
    });
  }

  String selectedDay = "";

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Select Date")),
      body: Padding(
        padding: EdgeInsets.all(16.0),
        child: Column(children: [
          DropdownButton<String>(
            items: suggestions.map((String suggestion) {
              return DropdownMenuItem<String>(
                value: suggestion,
                onTap: () => selectDay(suggestion),
                child: Text(suggestion),
              );
            }).toList(),
            onChanged: selectDay,
            value: selectedDay,
          ),
          ElevatedButton(
            onPressed: () {},
            child: Text("Confirm Selection"),
          ),
        ]),
      ),
    );
  }
}
